import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERROR', d); sys.exit()
for u in d['members']:
    real=u.get('profile',{}).get('real_name','')
    if real.lower().find('diego')>=0 or u.get('display_name','').lower().find('diego')>=0:
        print(u['id'], '|', u.get('real_name'), '|', u.get('display_name'))
"

