arguments.command:
curl -s -X POST "https://slack.com/api/conversations.history" -H "Authorization: Bearer <TOKEN>" -d "channel=C_DEP&limit=100" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERROR', d); sys.exit()
for m in d['messages']:
    text=(m.get('text') or '').replace(chr(10),' / ')
    if 'rollback' in text.lower() or 'diego' in m.get('user','').lower():
        print(m['ts'], '|', m['user'], '|', text[:300])
        if 'reactions' in m:
            for r in m['reactions']:
                print('   reaction:', r['name'], r['count'])
"

